MediaInfoHostApiForNativeInterop? pigeon_getInstance_MediaInfoHostApi({
  String channelName = defaultInstanceName,
}) => _MediaInfoHostApiForNativeInterop.getInstance(channelName: channelName);

class _MediaInfoHostApiForNativeInterop
    implements MediaInfoHostApiForNativeInterop {
  _MediaInfoHostApiForNativeInterop._withRegistrar({
    jni_bridge.MediaInfoHostApiRegistrar? jniApi,
    ffi_bridge.MediaInfoHostApiSetup? ffiApi,
  }) : _jniApi = jniApi,
       _ffiApi = ffiApi;

  /// Returns instance of MediaInfoHostApiForNativeInterop with specified [channelName] if one has been registered.
  ///
  /// Returns the instance registered by this isolate's engine when it is known,
  /// and otherwise the most recent registration.
  static MediaInfoHostApiForNativeInterop? getInstance({
    String channelName = defaultInstanceName,
  }) {
    if (Platform.isAndroid) {
      final int? engineId = PlatformDispatcher.instance.engineId;
      final JString jName = channelName.toJString();
      final jni_bridge.MediaInfoHostApiRegistrar? link;
      try {
        link = jni_bridge.MediaInfoHostApiRegistrar.pigeonResolveInstance(
          engineId ?? _pigeonNoEngineKey,
          _pigeonEngineAffinity ?? _pigeonNoEngineKey,
          jName,
        );
      } finally {
        jName.release();
      }
      if (link == null) {
        _throwNoInstanceError(channelName);
      }
      if (link != null && _pigeonEngineAffinity == null) {
        final int linkEngineKey =
            jni_bridge.MediaInfoHostApiRegistrar.pigeonEngineKeyOf(link);
        if (linkEngineKey != _pigeonNoEngineKey &&
            (engineId == null || linkEngineKey < 0)) {
          _pigeonEngineAffinity = linkEngineKey;
        }
      }
      return _MediaInfoHostApiForNativeInterop._withRegistrar(jniApi: link);
